mapper.select:
SELECT r.`novel_id`, t.`name` FROM `novel_tag_relation` r INNER JOIN `novel` n ON n.`id` = r.`novel_id` AND n.`user_id` = r.`user_id` INNER JOIN `novel_tag` t ON t.`id` = r.`tag_id` AND t.`user_id` = r.`user_id` WHERE r.`user_id` = #{userId} AND r.`novel_id` IN
#{novelId}
ORDER BY r.`novel_id`, t.`name`, t.`id`
